import { describe, expect, it } from 'vitest';
import { nodeBoxes, readGlb } from './glb.js';
import { COIN_RADIUS } from '../src/game/physics.js';
import {
  CABINET_BED_LENGTH, GAME, machineGeometryFor, PALETTE,
} from '../src/game/config.js';

// The cabinet shell is generated by tools/build_cabinet.py, so what needs testing is not a
// function but an artefact: does the committed GLB still stand where the design says, and does it
// still leave every moving part of the machine room to move? See
// docs/superpowers/specs/2026-09-08-cabinet-shell-design.md.
//
// glTF space is exactly the script's authoring space. export_yup maps Blender (bx, by, bz) to
// (bx, bz, -by), and the script authors bx = world x, by = -z_local, bz = world y - so a glTF
// coordinate reads straight off as (world x, world y, z_local). No conversion here.
const MODEL = 'public/models/cabinet.glb';

// 9.06 / 2. layoutGeometry mounts the model at lowerCenterZ and scales it by lowerLength / 9.06,
// which pins z_local -/+ this to the bed's front and back lip at every geometry setting.
const HALF_DEFAULT_BED = CABINET_BED_LENGTH / 2;

// Ranges straight from the design's parts table: [x, y, z_local], each [min, max].
const box = (x, y, z) => ({ x, y, z });
const mirror = (name, spec) => ({
  [`${name}_L`]: box([-spec.x[1], -spec.x[0]], spec.y, spec.z),
  [`${name}_R`]: spec,
});

// Seven newels define six bays, numbered from the player back to the pin board's sill, where the
// fence ends (tools/build_cabinet.py FENCE_END).
const FENCE_END = 2.42;
const FENCE_NEWELS = Array.from({ length: 7 }, (_, j) => -4.38 + ((FENCE_END + 4.38) / 6) * j);
const FENCE_BAYS = FENCE_NEWELS.slice(0, -1).map((c, j) => (c + FENCE_NEWELS[j + 1]) / 2);

const PARTS = {
  ...mirror('shell_side', box([4.55, 4.85], [-2.55, 1.58], [-4.53, 5.22])),
  ...Object.assign({}, ...FENCE_NEWELS.map((c, j) => mirror(
    `fence_newel_${j}`, box([4.54, 4.78], [1.58, 2.46], [c - 0.12, c + 0.12]),
  ))),
  ...mirror('fence_handrail', box([4.56, 4.78], [2.25, 2.375], [-4.50, FENCE_END + 0.12])),
  ...mirror('fence_lower_rail', box([4.50, 4.76], [1.72, 1.80], [-4.38, FENCE_END])),
  ...Object.assign({}, ...FENCE_BAYS.map((c, j) => mirror(
    `fence_baluster_${j + 1}`, box([4.50, 4.64], [1.80, 2.25], [c - 0.035, c + 0.035]),
  ))),
  ...Object.assign({}, ...FENCE_BAYS.map((c, j) => mirror(
    `fence_lamp_${j + 1}`, box([4.49, 4.55], [2.16, 2.24], [c - 0.16, c + 0.16]),
  ))),
  ...mirror('trim_gold_rail_lo', box([4.84, 4.86], [-0.025, 0.025], [-4.53, 5.22])),
  back_shell: box([-4.85, 4.85], [-2.55, 3.30], [5.22, 5.42]),

  ...mirror('front_bezel', box([4.55, 4.85], [-2.00, 2.60], [-4.53, -4.33])),
  front_panel_lower: box([-4.85, 4.85], [-2.00, 0.00], [-4.53, -4.33]),
  ...mirror('front_glow', box([4.51, 4.55], [0.00, 2.60], [-4.53, -4.50])),

  plinth: box([-4.35, 4.35], [-2.76, -2.55], [-4.43, 4.97]),
  // On the outer face, on the same plane as the gold rails - not inside the plinth's inset, where
  // it was invisible behind the body's own overhang.
  ...mirror('plinth_glow', box([4.84, 4.86], [-2.52, -2.44], [-4.43, 4.97])),

};

// Solid volumes the shell must stay out of, derived per geometry setting. Each is an open box:
// touching a face is not intruding, which is what lets the front panel sit flush on the bed lip
// and the bezel sit flush above the glass.
//
// Every one of them is bounded BELOW by the bed surface at y = 0. That bound is the whole reason
// the plinth and the lower front panel are legal: coins and chests live above the bed, and the
// cabinet's structure lives below it. Drop the lower bound and the plinth reads as an intrusion
// into the coin rain channel it sits two and a half units underneath.
function envelopes(geometry) {
  const bedSpan = [geometry.lowerFrontZ, geometry.lowerBackZ];
  return [
    {
      // Coin space plus the side glass, which stays procedural and visible. The ceiling is the
      // glass top, not the neon bars at 2.27 - those are decor the model replaces.
      label: 'playfield interior and side glass',
      x: [-4.25, 4.25],
      y: [0, 2.15],
      z: bedSpan,
    },
    {
      label: 'chest drop channel',
      x: [-(GAME.playfieldHalfWidth - GAME.chestWidth), GAME.playfieldHalfWidth - GAME.chestWidth],
      y: [0, GAME.chestStartY],
      z: [geometry.scraperZ - 0.45, geometry.scraperZ + 0.45],
    },
  ];
}

// The scripted launch arc, sampled. A path is not a volume: treating it as one would ban the
// whole region under the arc, which is where the machine's own front bezel has to live.
function arcSamples(geometry, steps = 50) {
  const points = [];
  for (let index = 0; index <= steps; index += 1) {
    const t = index / steps;
    const eased = 1 - (1 - t) ** 2;
    points.push({
      z: GAME.launcherMuzzleZ + (geometry.dropZoneZ - GAME.launcherMuzzleZ) * eased,
      y: GAME.launcherMuzzleY + (GAME.launcherLandingY - GAME.launcherMuzzleY) * eased
        + Math.sin(Math.PI * t) * GAME.launcherArcHeight,
    });
  }
  return points;
}

// Mount transform: z_world = lowerCenterZ + (lowerLength / 9.06) * z_local. x and y never move.
const toWorldZ = (geometry, zLocal) =>
  geometry.lowerCenterZ + (geometry.lowerLength / CABINET_BED_LENGTH) * zLocal;

const overlaps = (a, b) => a[0] < b[1] - 1e-9 && b[0] < a[1] - 1e-9;

// Corners of every slider that moves something this model has to clear. lowerCenterZ and
// lowerLength move the model itself; upperCenterZ drives dropZoneZ, which is where the launch arc
// ends; scraperZ is the chest channel. machineGeometryFor clamps and derives, so an unreachable
// pair here comes back as the nearest reachable one rather than a fantasy layout.
const CORNERS = [];
for (const lowerCenterZ of [-0.45, 1.2]) {
  for (const lowerLength of [7.6, 13]) {
    for (const upperCenterZ of [1.2, 2.4]) {
      for (const scraperZ of [2.9, 6]) {
        CORNERS.push(machineGeometryFor({ lowerCenterZ, lowerLength, upperCenterZ, scraperZ }));
      }
    }
  }
}

describe('cabinet shell model', () => {
  const gltf = readGlb(MODEL);
  const boxes = nodeBoxes(gltf);

  it('ships no textures and the specified cabinet materials', () => {
    expect(gltf.images ?? []).toHaveLength(0);
    expect(gltf.materials.map((material) => material.name).sort())
      .toEqual(['fence_lamp', 'neon_gold', 'neon_teal', 'rail_brass', 'shell_dark', 'trim_gold']);
    expect(gltf.extensionsUsed).toContain('KHR_materials_emissive_strength');
  });

  it('uses non-emissive palette brass and independently addressable mint lamps', () => {
    const linear = (hex) => [16, 8, 0].map((shift) => {
      const value = ((hex >> shift) & 255) / 255;
      return value <= 0.04045 ? value / 12.92 : ((value + 0.055) / 1.055) ** 2.4;
    });
    const brass = gltf.materials.find(({ name }) => name === 'rail_brass');
    expect(brass).toBeDefined();
    const pbr = brass.pbrMetallicRoughness;
    linear(PALETTE.gold).forEach((value, axis) => expect(pbr.baseColorFactor[axis]).toBeCloseTo(value, 6));
    expect(pbr.metallicFactor).toBeCloseTo(0.80, 6);
    expect(pbr.roughnessFactor).toBeCloseTo(0.34, 6);
    expect(brass.emissiveFactor ?? [0, 0, 0]).toEqual([0, 0, 0]);
    const lamps = gltf.nodes.filter(({ name }) => name.startsWith('fence_lamp_'));
    expect(lamps).toHaveLength(12);
    for (const node of lamps) {
      const primitives = gltf.meshes[node.mesh].primitives;
      expect(primitives).toHaveLength(1);
      const lamp = gltf.materials[primitives[0].material];
      expect(lamp.name).toBe('fence_lamp');
      const strength = lamp.extensions?.KHR_materials_emissive_strength?.emissiveStrength ?? 1;
      linear(PALETTE.mint).forEach((value, axis) => {
        expect(lamp.pbrMetallicRoughness.baseColorFactor[axis]).toBeCloseTo(value, 6);
        expect(lamp.emissiveFactor[axis] * strength).toBeCloseTo(value * 0.6, 6);
      });
    }
  });

  it('holds exactly the parts the design lists', () => {
    expect(boxes.map((entry) => entry.name).sort()).toEqual(Object.keys(PARTS).sort());
  });

  // Without this the numbers in the design document are decoration.
  describe('each part stands where the design says', () => {
    for (const { name, min, max } of boxes) {
      it(name, () => {
        const spec = PARTS[name];
        for (const [axis, label] of [[0, 'x'], [1, 'y'], [2, 'z_local']]) {
          expect(min[axis], `${name} ${label} min`).toBeGreaterThanOrEqual(spec[label === 'z_local' ? 'z' : label][0] - 0.01);
          expect(max[axis], `${name} ${label} max`).toBeLessThanOrEqual(spec[label === 'z_local' ? 'z' : label][1] + 0.01);
        }
      });
    }
  });

  it('pins the front face and the bed lip to the same plane at every setting', () => {
    for (const geometry of CORNERS) {
      expect(toWorldZ(geometry, -HALF_DEFAULT_BED)).toBeCloseTo(geometry.lowerFrontZ, 9);
      expect(toWorldZ(geometry, HALF_DEFAULT_BED)).toBeCloseTo(geometry.lowerBackZ, 9);
    }
  });

  // The bug this guards: the mount scaled by the default bed length instead of the length the model
  // is authored around, so shortening the default bed left the cabinet's front 0.38 proud of the lip.
  it('never reaches in front of the bed\'s lip', () => {
    for (const geometry of CORNERS) {
      for (const { name, min } of boxes) {
        // 1e-4, not 0: glTF accessor bounds are float32, so the flush front face reads a hair early.
        expect(toWorldZ(geometry, min[2]), `${name} at lowerCenterZ ${geometry.lowerCenterZ}`)
          .toBeGreaterThan(geometry.lowerFrontZ - 1e-4);
      }
    }
  });

  it('leaves the solid clearance envelopes empty at every setting', () => {
    for (const geometry of CORNERS) {
      for (const envelope of envelopes(geometry)) {
        for (const { name, min, max } of boxes) {
          const world = [
            [min[0], max[0]],
            [min[1], max[1]],
            [toWorldZ(geometry, min[2]), toWorldZ(geometry, max[2])],
          ];
          const hit = overlaps(world[0], envelope.x)
            && overlaps(world[1], envelope.y)
            && overlaps(world[2], envelope.z);
          expect(hit, `${name} intrudes ${envelope.label} at lowerLength ${geometry.lowerLength}`)
            .toBe(false);
        }
      }
    }
  });

  // Sight lines. This is the failure mode that got through twice by eye - a lit strip and then a
  // structural bezel across the top of the front opening, each of which read as a bar hanging in
  // front of the machine. The geometry is counter-intuitive: the camera sits at y 5.4 and looks
  // DOWN, so a sight line to the bed crosses the front plane high, not low. The bed's own far end
  // needs the opening clear to y 3.52 there, the scraper's top to 4.15 - both above the shell's
  // 2.60 roof - so a top member does not work at any height, and the front opening simply has to
  // be open upwards.
  //
  // Unlike the clearance envelopes this one IS tied to the camera: move setupScene's camera and
  // these numbers have to be re-derived. That is the price of catching it automatically, and the
  // camera has not moved in a long time.
  it('leaves the playfield in plain sight from the game camera', () => {
    const CAMERA = [0, 5.4, -9.4];

    // Slab method, parametrised so t = 1 is the target. A hit strictly between the camera and the
    // target is an occluder; touching a face is not.
    const blocks = (target, min, max) => {
      let near = 0;
      let far = 1;
      for (let axis = 0; axis < 3; axis += 1) {
        const origin = CAMERA[axis];
        const delta = target[axis] - origin;
        if (Math.abs(delta) < 1e-12) {
          if (origin <= min[axis] || origin >= max[axis]) return false;
          continue;
        }
        const a = (min[axis] - origin) / delta;
        const b = (max[axis] - origin) / delta;
        near = Math.max(near, Math.min(a, b));
        far = Math.min(far, Math.max(a, b));
        if (near >= far) return false;
      }
      return far > 1e-6 && near < 1 - 1e-6;
    };

    for (const geometry of CORNERS) {
      const world = boxes.map(({ name, min, max }) => ({
        name,
        min: [min[0], min[1], toWorldZ(geometry, min[2])],
        max: [max[0], max[1], toWorldZ(geometry, max[2])],
      }));
      // The surfaces a player has to read: the lower bed and the upper tray, across the width a
      // coin can reach.
      for (const y of [0, GAME.upperTrayY + GAME.upperTrayHeight / 2]) {
        for (const x of [-(GAME.playfieldHalfWidth - COIN_RADIUS), 0, GAME.playfieldHalfWidth - COIN_RADIUS]) {
          const from = geometry.lowerFrontZ + 0.5;
          const to = geometry.lowerBackZ - 0.3;
          for (let step = 0; step <= 16; step += 1) {
            const target = [x, y, from + ((to - from) * step) / 16];
            for (const part of world) {
              expect(
                blocks(target, part.min, part.max),
                `${part.name} blocks the view of (${x.toFixed(1)}, ${y.toFixed(2)}, ${target[2].toFixed(2)}) at lowerLength ${geometry.lowerLength}`,
              ).toBe(false);
            }
          }
        }
      }
    }
  });

  it('leaves the launch arc clear at every setting', () => {
    const halfWidth = GAME.launcherTravelHalfWidth;
    for (const geometry of CORNERS) {
      for (const point of arcSamples(geometry)) {
        for (const { name, min, max } of boxes) {
          if (point.y <= min[1] || point.y >= max[1]) continue;
          const zSpan = [toWorldZ(geometry, min[2]), toWorldZ(geometry, max[2])];
          if (point.z <= zSpan[0] || point.z >= zSpan[1]) continue;
          // The coin's x is the aim, anywhere across the travel; the part is only clear if it
          // misses the whole band.
          const inBand = overlaps([min[0], max[0]], [-halfWidth - COIN_RADIUS, halfWidth + COIN_RADIUS]);
          expect(inBand, `${name} blocks the arc at z ${point.z.toFixed(2)} y ${point.y.toFixed(2)}`)
            .toBe(false);
        }
      }
    }
  });
});

